"""Files not worth an LLM's time or tokens: tests, bundled or generated output, empty files and boilerplate
(a blank `__init__.py`, a scaffolded Frappe controller, a barrel file that only re-exports)."""

from __future__ import annotations

import ast
import re
from collections import Counter
from pathlib import Path, PurePosixPath

from codecheck.diff import read_file_content
from codecheck.models import ReviewTarget

TEST_DIRS = {"test", "tests", "__tests__", "spec", "specs", "e2e", "cypress", "__mocks__"}
BUNDLE_DIRS = {"dist", "node_modules", "vendor", "bower_components", ".next", ".nuxt", "coverage", "site-packages", "__pycache__"}
BUILD_SUFFIXES = {".js", ".mjs", ".cjs", ".css"}   # a `build/` folder of these is output; `build/` Python is source
TEST_NAME = re.compile(r"(^test_.*\.py$)|(_test\.(py|go)$)|(\.(test|spec|cy)\.[cm]?[jt]sx?$)|(Tests?\.(java|cs|kt)$)")
BUNDLE_NAME = re.compile(r"(\.min\.(js|css)$)|(\.chunk\.js$)|(\.map$)|(\.umd\.js$)|(^(bundle|vendor)\.js$)")
# `*.bundle.js` is a built file in most toolchains but hand-written source in Frappe, so go by what is inside
BUNDLE_LIKE_NAME = re.compile(r"(\.bundle\.(js|css)$)|(-bundle\.)")
BUILT_MARK = re.compile(r"__webpack_require__|webpackBootstrap|sourceMappingURL=|\bparcelRequire\b|Object\.defineProperty\(exports, ?[\"']__esModule")
GENERATED_NAME = re.compile(r"_pb2(_grpc)?\.py$")
GENERATED_HEAD = re.compile(r"auto-?generated|do not edit|generated by|this file is generated|@generated", re.I)
BLOCK_COMMENT = re.compile(r"/\*.*?\*/", re.S)
LINE_COMMENT = re.compile(r"^\s*(//|#).*$", re.M)
REEXPORT = re.compile(r"""^(import\s.+\sfrom\s.+|import\s+['"].+['"]|export\s+\*\s+from\s.+|export\s*\{[^}]*\}\s*from\s.+|export\s+\*\s+as\s+\w+\s+from\s.+);?$""")
# `frappe.ui.form.on("X", { refresh(frm) { /* write your code here */ } })` once the comments are gone
EMPTY_FRAPPE_FORM = re.compile(r"""^frappe\.ui\.form\.on\(\s*['"][^'"]+['"]\s*,\s*\{\s*((\w+\s*(:\s*function)?\s*\(\s*\w*\s*\)\s*\{\s*\}\s*,?\s*)*)\}\s*\)\s*;?$""")


def by_path(path: str) -> str | None:
    p = PurePosixPath(path)
    parts, name = set(p.parts[:-1]), p.name
    if parts & TEST_DIRS or TEST_NAME.search(name) or p.stem in {"tests", "test", "conftest"}:
        return "test"
    if parts & BUNDLE_DIRS or BUNDLE_NAME.search(name) or ("build" in parts and p.suffix in BUILD_SUFFIXES):
        return "bundle"
    if GENERATED_NAME.search(name):
        return "generated"
    return None


def _python_boilerplate(src: str) -> bool:
    """Only imports, docstrings, `pass`, dunder assignments (`__version__`) and classes that are just `pass`."""
    try:
        body = ast.parse(src).body
    except (SyntaxError, ValueError):
        return False

    def dunder(node) -> bool:
        targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        return all(isinstance(t, ast.Name) and t.id.startswith("__") and t.id.endswith("__") for t in targets)

    def trivial(node) -> bool:
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            return dunder(node)
        if isinstance(node, (ast.Import, ast.ImportFrom, ast.Pass, ast.Expr, ast.If)):
            return trivial_stmt(node)
        if isinstance(node, ast.ClassDef):
            return not node.decorator_list and all(trivial_stmt(s) for s in node.body)
        return False

    def trivial_stmt(node) -> bool:
        if isinstance(node, (ast.Pass, ast.Import, ast.ImportFrom)):
            return True
        if isinstance(node, ast.AnnAssign):
            return node.value is None                     # a bare annotation, as in Frappe's generated types block
        if isinstance(node, ast.If):                      # `if TYPE_CHECKING:` with only imports and annotations
            return isinstance(node.test, ast.Name) and node.test.id == "TYPE_CHECKING" and not node.orelse and all(trivial_stmt(s) for s in node.body)
        return isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant)
    return bool(body) and all(trivial(n) for n in body)


def by_content(path: str, src: str) -> str | None:
    if not src.strip():
        return "empty"
    lines = src.splitlines()
    if max(map(len, lines)) > 1500 or (len(src) > 5000 and len(src) / len(lines) > 300):
        return "bundle"                                   # minified
    header = []                                           # the leading comment block only: a Frappe controller's
    for line in lines[:8]:                                # "# begin: auto-generated types" is inside real code
        if line.strip() and not line.lstrip().startswith(("#", "//", "/*", "*", '"""')):
            break
        header.append(line)
    if GENERATED_HEAD.search("\n".join(header)):
        return "generated"
    if BUNDLE_LIKE_NAME.search(path) and BUILT_MARK.search(src):
        return "bundle"
    if path.endswith(".py"):
        try:
            if not ast.parse(src).body:
                return "empty"                            # only comments
        except (SyntaxError, ValueError):
            pass
        return "boilerplate" if _python_boilerplate(src) else None
    code = LINE_COMMENT.sub("", BLOCK_COMMENT.sub("", src))
    statements = [line.strip() for line in code.splitlines() if line.strip()]
    if not statements:
        return "empty"
    if all(REEXPORT.match(line) for line in statements):
        return "boilerplate"
    if EMPTY_FRAPPE_FORM.match(" ".join(statements)):
        return "boilerplate"
    return None


def partition(targets: list[ReviewTarget], repo_path: Path) -> tuple[list[ReviewTarget], Counter]:
    """(files worth sending, how many were left out per category)."""
    kept, left_out = [], Counter()
    for t in targets:
        why = by_path(t.path)
        if not why and t.status != "deleted":
            src = read_file_content(repo_path, t)
            why = by_content(t.path, src) if src is not None else None
        if why:
            left_out[why] += 1
        else:
            kept.append(t)
    return kept, left_out


LABELS = {"test": "tests", "bundle": "bundled or minified", "generated": "generated", "empty": "empty", "boilerplate": "boilerplate"}


def summary(left_out: Counter) -> str:
    n = sum(left_out.values())
    return f"{n} file(s) not sent to the AI ({', '.join(f'{c} {LABELS[k]}' for k, c in left_out.most_common())})"
